const hier = $input.first().json;
const payload = JSON.parse($('Документ + вопрос').first().json.payload);
function splitSentencesWithSpans(text) {
  const sentences = text.split(/(?<=[.!?])\s+/);
  const out = []; let pos = 0;
  for (const sent of sentences) {
    if (!sent.trim()) continue;
    let idx = text.indexOf(sent, pos); if (idx === -1) idx = pos;
    const sStart = idx, sEnd = idx + sent.length;
    out.push({start: sStart, end: sEnd, text: sent});
    pos = sEnd;
  }
  return out;
}
const sentences = splitSentencesWithSpans(payload.document);
return [{json: {
  question: hier.question,
  found_child_text: hier.found_child_text,
  model_answer: hier.model_answer,
  gap_threshold: (payload.gap_threshold !== undefined) ? payload.gap_threshold : 0.15,
  sentences: sentences
}}];

const d = $('Нарезка семантическая: предложения').first().json;
const resp = $input.first().json;
function cosine(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i]*b[i]; na += a[i]*a[i]; nb += b[i]*b[i]; }
  return dot / (Math.sqrt(na) * Math.sqrt(nb));
}
const vecs = resp.data.map(x => x.embedding);
const sentences = d.sentences;
const threshold = d.gap_threshold;
const gaps = [];
for (let i = 0; i < vecs.length - 1; i++) { gaps.push(1 - cosine(vecs[i], vecs[i+1])); }
const chunks = []; let curStart = sentences[0].start, curEnd = sentences[0].end, curN = 1;
for (let i = 0; i < sentences.length - 1; i++) {
  const gap = gaps[i];
  if (gap > threshold) {
    chunks.push({start: curStart, end: curEnd, n_sentences: curN, cut_after_gap: gap});
    curStart = sentences[i+1].start; curEnd = sentences[i+1].end; curN = 1;
  } else {
    curEnd = sentences[i+1].end; curN += 1;
  }
}
chunks.push({start: curStart, end: curEnd, n_sentences: curN, cut_after_gap: null});
return [{json: {
  question: d.question,
  found_child_text: d.found_child_text,
  model_answer: d.model_answer,
  gap_threshold: threshold,
  n_sentences: sentences.length,
  gaps: gaps.map(g => Math.round(g * 10000) / 10000),
  n_chunks: chunks.length,
  chunks: chunks
}}];

const d = $input.first().json;
const payload = JSON.parse($('Документ + вопрос').first().json.payload);
function splitLevel(text, level) {
  let parts;
  if (level === 0) parts = text.split(/\n\n+/);
  else if (level === 1) parts = text.split('\n');
  else if (level === 2) parts = text.split(/(?<=[.!?])\s+/);
  else if (level === 3) parts = text.split(' ');
  else parts = text.split('');
  return parts.filter(p => p !== '');
}
const LEVEL_NAME = ['абзац', 'строка', 'предложение', 'слово', 'символ'];
const LEVEL_JOINER = ['\n\n', '\n', ' ', ' ', ''];
function packGreedy(pieces, target, joiner) {
  const chunks = []; let cur = []; let curLen = 0;
  for (const p of pieces) {
    const extra = p.length + (cur.length ? joiner.length : 0);
    if (cur.length && curLen + extra > target) {
      chunks.push(cur.join(joiner)); cur = [p]; curLen = p.length;
    } else { cur.push(p); curLen += extra; }
  }
  if (cur.length) chunks.push(cur.join(joiner));
  return chunks;
}
function recursiveSplit(text, target, level, trace) {
  if (level >= 5) return [text];
  const pieces = splitLevel(text, level);
  if (pieces.length <= 1) return recursiveSplit(text, target, level + 1, trace);
  trace.hits[level] = (trace.hits[level] || 0) + 1;
  const joiner = LEVEL_JOINER[level];
  let good = []; const out = [];
  for (const p of pieces) {
    if (p.length <= target) { good.push(p); }
    else {
      trace.oversized[level] = (trace.oversized[level] || 0) + 1;
      if (good.length) { out.push(...packGreedy(good, target, joiner)); good = []; }
      out.push(...recursiveSplit(p, target, level + 1, trace));
    }
  }
  if (good.length) out.push(...packGreedy(good, target, joiner));
  return out;
}
const target = payload.chunk_size_v1 || 180;
const trace = {hits: {}, oversized: {}};
const chunks = recursiveSplit(payload.document, target, 0, trace);
const traceNamed = {};
for (const k in trace.hits) traceNamed[LEVEL_NAME[k] + '_hits'] = trace.hits[k];
for (const k in trace.oversized) traceNamed[LEVEL_NAME[k] + '_oversized'] = trace.oversized[k];
return [{json: {
  question: d.question,
  found_child_text: d.found_child_text,
  model_answer: d.model_answer,
  gap_threshold: d.gap_threshold,
  n_sentences: d.n_sentences,
  gaps: d.gaps,
  n_chunks_semantic: d.n_chunks,
  recursive_target: target,
  recursive_n_chunks: chunks.length,
  recursive_chunk_lengths: chunks.map(c => c.length),
  recursive_trace: traceNamed,
  recursive_chunks_preview: chunks.map(c => c.length > 60 ? c.slice(0, 57) + '...' : c)
}}];
